"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["69522"],{63452(n){n.exports=JSON.parse('{"id":"FIN-1249","slug":"financial-contagion","term":"Financial Contagion","also_known_as":[],"difficulty":"Advanced","definition":"Financial contagion is the spread of financial problems, such as market crashes, bank failures or currency crises, from one country, market or institution to others.","explanation":["Financial systems are closely connected. When a crisis hits one part of the system, it can spread through direct links, such as banks lending to each other, and through indirect channels, such as investors selling assets elsewhere to cover losses or losing confidence in similar markets.","For example, the Asian financial crisis of 1997 began in Thailand and quickly spread to Indonesia, South Korea and other countries, as investors withdrew money from the region. The 2008 financial crisis began in the US housing and mortgage markets but spread globally through banks and investment funds that held related securities.","Contagion can occur even when the affected countries or institutions are fundamentally sound, because investors may assume they share similar weaknesses or need to sell assets to raise cash.","Regulators try to limit contagion through capital and liquidity requirements for banks, deposit insurance, central bank support in crises, clearing houses and international cooperation. Understanding contagion is central to managing systemic risk."],"note":"","total":1500,"prev":{"slug":"financial-close","term":"Financial Close"},"next":{"slug":"financial-covenant","term":"Financial Covenant"}}')}}]);